  var currentTokens = 0;
  for (final message in messages) {
    final tokens = estimateStringTokens(serializeConversation([message]));
    if (current.isNotEmpty && currentTokens + tokens > budgetTokens) {
      chunks.add(current);
      current = <Message>[];
      currentTokens = 0;
