final class StructuredCompactor {
  /// Creates a compactor over [session]/[state].
  StructuredCompactor({
    required this.session,
    required this.state,
    required this.window,
    required this.settings,
    required this.judge,
    required this.summarize,
    required this.checkpointPrompt,
    this.hooks,
